      ],
      "claims": [
        {
          "text": "The private information removal process is an exceptional service only for high-risk content that violates GitHub's Terms of Service, such as exposed access credentials.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        },
        {
          "text": "\"Private information\" means content that should have been kept confidential and whose public availability poses a specific or targeted security risk.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        },
        {
          "text": "Private information removal requests are not appropriate for internal server names, IP addresses, and URLs on their own, unless you can show their use poses a security threat.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        },
        {
          "text": "Private information removal requests are not appropriate for mere mentions of your company's identity, name, brand, domain name, or other references to your company in files on GitHub, unless you can articulate why the use is a threat to your company's security posture.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        },
        {
          "text": "Private information removal requests are not appropriate for entire files or repositories that do not pose a specific security risk but that you believe are otherwise objectionable.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        },
        {
          "text": "Private information removal requests are not appropriate for content that may infringe your or your organization's copyright rights; such matters are handled under the DMCA Takedown Policy instead.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        },
        {
          "text": "Private information removal requests are not appropriate for trademark disputes; such matters are handled under the Trademark Policy instead.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        },
        {
          "text": "Privacy complaints — requests to access, transfer, change, or delete your personal information on GitHub — go through the Privacy contact form.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        },
        {
          "text": "Private information removal requests are not appropriate for content governed by the Community Guidelines, such as malware or general-purpose tools.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        },
        {
          "text": "The private information removal process cannot be used to remove other kinds of content, such as potentially infringing content, and cannot process other removal requests simultaneously with private information removal requests.",
          "support_status": "supported",
          "citation_status": "supported",
          "note": ""
        }
      ]
    }
  }
}

